     1	package com.pousada.plan;
     2	
     3	import com.pousada.domain.Money;
     4	import com.pousada.domain.Room;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	import java.time.temporal.ChronoUnit;
     9	
    10	/** O que um plano precisa saber da reserva para validar e calcular o preço. */
    11	public record PricingRequest(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    12	
    13	    public int nights() {
    14	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    15	    }
    16	
    17	    /** Soma das diárias do quarto, cada noite já arredondada e com a temporada aplicada. */
    18	    public BigDecimal sumOfNights() {
    19	        BigDecimal sum = Money.ZERO;
    20	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    21	            sum = sum.add(room.priceOfNight(night));
    22	        }
    23	        return sum;
    24	    }
    25	}
=== src/main/java/com/pousada/plan/RatePlan.java
     1	package com.pousada.plan;
     2	
     3	import com.pousada.domain.Money;
     4	
     5	import java.math.BigDecimal;
     6	
     7	/**
     8	 * Um plano de tarifa. Cada plano muda apenas o que é dele: quem pode usá-lo, a soma das diárias,
     9	 * o desconto e a devolução no cancelamento. A sequência de cálculo é a mesma para todos.
    10	 */
    11	public interface RatePlan {
    12	
    13	    String code();
    14	
    15	    /** Lança ApiException (INVALID_REQUEST) quando o plano não pode ser usado nesta reserva. */
    16	    default void validate(PricingRequest request) {
    17	    }
    18	
    19	    default BigDecimal subtotal(PricingRequest request) {
    20	        return request.sumOfNights();
    21	    }
    22	
    23	    default BigDecimal discount(PricingRequest request, BigDecimal subtotal) {
    24	        return Money.ZERO;
    25	    }
    26	
    27	    /** Quanto volta ao hóspede quando cancela, dado o que ele pagou. */
    28	    default BigDecimal refund(BigDecimal amountPaid) {
    29	        return amountPaid;
    30	    }
    31	
    32	    default PriceQuote quote(PricingRequest request) {
    33	        validate(request);
    34	        BigDecimal subtotal = subtotal(request);
    35	        BigDecimal discount = discount(request, subtotal);
    36	        return new PriceQuote(request.nights(), subtotal, discount, subtotal.subtract(discount));
    37	    }
    38	}
