     3	import java.util.List;
     4	import java.util.Map;
     5	import java.util.Optional;
     6	import java.util.function.Function;
     7	import java.util.stream.Collectors;
     8	
     9	/** Único lugar que conhece os planos existentes: um plano novo entra só nesta lista. */
    10	public class RatePlans {
    11	
    12	    private final Map<String, RatePlan> byCode;
    13	
    14	    public RatePlans(List<RatePlan> plans) {
    15	        this.byCode = plans.stream().collect(Collectors.toUnmodifiableMap(RatePlan::code, Function.identity()));
    16	    }
    17	
    18	    public static RatePlans defaults() {
    19	        return new RatePlans(List.of(
    20	                new StandardPlan(),
    21	                new NonRefundablePlan(),
    22	                new CorporatePlan(),
    23	                new WeekendPackagePlan(),
    24	                new LongStayPlan()));
    25	    }
    26	
    27	    public Optional<RatePlan> find(String code) {
    28	        return Optional.ofNullable(byCode.get(code));
    29	    }
    30	
    31	    public RatePlan get(String code) {
    32	        return find(code).orElseThrow(() -> new IllegalStateException("Plano desconhecido: " + code));
    33	    }
    34	}
