     6	public final class Money {
     7	
     8	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
     9	
    10	    private Money() {
    11	    }
    12	
    13	    public static BigDecimal round(BigDecimal value) {
    14	        return value.setScale(2, RoundingMode.HALF_EVEN);
    15	    }
    16	
    17	    public static BigDecimal of(String value) {
    18	        return round(new BigDecimal(value));
    19	    }
    20	
    21	    public static BigDecimal percent(BigDecimal amount, String rate) {
    22	        return round(amount.multiply(new BigDecimal(rate)));
    23	    }
    24	}
