     1	package com.pousada.domain;
     2	
     3	import com.fasterxml.jackson.annotation.JsonIgnore;
     4	import com.pousada.error.ApiException;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	
     9	public record Reservation(
    10	        long id,
    11	        int roomNumber,
    12	        String guestName,
    13	        String guestEmail,
    14	        String guestCpf,
    15	        LocalDate checkIn,
    16	        LocalDate checkOut,
    17	        int guests,
    18	        String ratePlan,
    19	        int nights,
    20	        BigDecimal subtotal,
    21	        BigDecimal discount,
    22	        BigDecimal total,
    23	        ReservationStatus status,
    24	        BigDecimal amountPaid,
    25	        BigDecimal refund,
    26	        @JsonIgnore String companyCode) {
    27	
    28	    public Reservation confirm() {
    29	        requireStatus("confirmar", ReservationStatus.PENDING);
    30	        return with(ReservationStatus.CONFIRMED, total, refund);
    31	    }
    32	
    33	    public Reservation checkInGuest() {
    34	        requireStatus("fazer check-in de", ReservationStatus.CONFIRMED);
    35	        return with(ReservationStatus.CHECKED_IN, amountPaid, refund);
    36	    }
    37	
    38	    public Reservation checkOutGuest() {
    39	        requireStatus("fazer check-out de", ReservationStatus.CHECKED_IN);
    40	        return with(ReservationStatus.CHECKED_OUT, amountPaid, refund);
    41	    }
    42	
    43	    public Reservation cancel(BigDecimal refundAmount) {
    44	        requireStatus("cancelar", ReservationStatus.PENDING, ReservationStatus.CONFIRMED);
    45	        return with(ReservationStatus.CANCELLED, amountPaid, refundAmount);
    46	    }
    47	
    48	    private void requireStatus(String action, ReservationStatus... allowed) {
    49	        for (ReservationStatus s : allowed) {
    50	            if (s == status) {
    51	                return;
    52	            }
    53	        }
    54	        throw ApiException.operationNotAllowed("Não é possível " + action + " uma reserva " + status);
    55	    }
    56	
    57	    private Reservation with(ReservationStatus newStatus, BigDecimal newPaid, BigDecimal newRefund) {
    58	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    59	                ratePlan, nights, subtotal, discount, total, newStatus, newPaid, newRefund, companyCode);
    60	    }
    61	}
