     5	public final class Season {
     6	
     7	    private Season() {
     8	    }
     9	
    10	    /** Alta temporada: de 15/12 ao fim de fevereiro e todo o mês de julho. */
    11	    public static boolean isHigh(LocalDate night) {
    12	        int month = night.getMonthValue();
    13	        return month == 1 || month == 2 || month == 7 || (month == 12 && night.getDayOfMonth() >= 15);
    14	    }
